from __future__ import annotations

from pathlib import Path
import argparse
import re

import pandas as pd


# ============================================================
# 74 - A-Type Separated Prediction
# ============================================================
#
# Purpose
# -------
# Read the already-created 64 all-514 prediction snapshot and
# create a SEPARATE A-type ranking without changing 64.
#
# Design principles
# -------
# - 64 remains the official normal prediction.
# - 74 does NOT recalculate V4.2_C scores.
# - 74 uses the frozen score/rank generated by 64.
# - A-type classification is conservative and rule-based.
# - Every included machine records which rule matched.
# - A candidate-review CSV is also saved for manual checking.
#
# Default flow
# -------
# 1) Run 64 for the target date.
# 2) Run this 74 script for the same target date.
# 3) Check 74_A_type_candidate_review_YYYYMMDD.csv once.
# 4) Keep the resulting prediction unchanged until actual data arrives.
# ============================================================


PROJECT_ROOT = Path(
    r"C:\Users\user\Desktop\Documents\SlotAnalyzer"
)

ANALYSIS_DIR = (
    PROJECT_ROOT
    / "data"
    / "maruhan_maebashi"
    / "machine_number"
    / "analysis_31days_deep"
)

SOURCE_64_DIR = (
    ANALYSIS_DIR
    / "64_Ver4_2_future_top10"
)

OUTPUT_DIR = (
    ANALYSIS_DIR
    / "74_Ver4_2_A_type_prediction"
)

TOP_N = 10
PRIMARY_N = 5


# ============================================================
# Conservative A-type whitelist
# ============================================================
#
# Important:
# These are NAME patterns, not guesses from performance.
# If a machine is not matched, it is excluded by default.
#
# Add a new pattern only after confirming the machine is meant
# to be handled as A-type in this project.
# ============================================================

A_TYPE_RULES: list[tuple[str, str]] = [
    # Juggler family
    ("JUGGLER", r"ジャグラー"),

    # HanaHana family
    ("HANAHANA", r"ハナハナ"),

    # Universal / A-project style machines
    ("HANABI", r"(^|[^ァ-ヶ])ハナビ|新ハナビ"),
    ("VERSUS", r"バーサス"),
    ("DISC_UP", r"ディスクアップ"),
    ("CRANKY", r"クランキー"),
    ("ALEX", r"アレックス"),
    ("THUNDER_V", r"サンダーV|サンダーＶ"),
    ("GETTER_MOUSE", r"ゲッターマウス"),

    # Other commonly treated A / bonus-type families
    ("NEW_PULSAR", r"ニューパルサー"),
    ("PULSAR", r"パルサー"),
    ("KEROT", r"ケロット"),
]


# Explicit exclusions override inclusions.
# Keep this short and only use it when a keyword can cause a false match.
A_TYPE_EXCLUDE_RULES: list[tuple[str, str]] = [
    # Example placeholders for future confirmed exceptions:
    # ("NOT_A_TYPE_EXAMPLE", r"機種名"),
]


# Useful words that may indicate a bonus/A-style machine but are NOT
# automatically included. They are listed in the review file only.
REVIEW_HINT_RULES: list[tuple[str, str]] = [
    ("BONUS_HINT", r"ボーナス"),
    ("A_TYPE_HINT", r"Aタイプ|Ａタイプ"),
    ("RT_HINT", r"\bRT\b|ＲＴ"),
]


# ============================================================
# Helpers
# ============================================================

def header(title: str) -> None:
    print()
    print("=" * 112)
    print(title)
    print("=" * 112)


def parse_args():
    parser = argparse.ArgumentParser(
        description=(
            "Create a separate A-type ranking from a frozen "
            "64 all-514 prediction snapshot."
        )
    )

    parser.add_argument(
        "--target-date",
        default=None,
        help=(
            "Target date YYYY-MM-DD. "
            "If omitted, use the newest 64_prediction_YYYYMMDD_all514.csv."
        ),
    )

    return parser.parse_args()


def read_csv_flexible(path: Path) -> pd.DataFrame:
    last_error = None

    for enc in (
        "utf-8-sig",
        "utf-8",
        "cp932",
    ):
        try:
            return pd.read_csv(
                path,
                encoding=enc,
            )
        except Exception as exc:
            last_error = exc

    raise RuntimeError(
        f"Could not read CSV: {path}\n"
        f"last_error={last_error}"
    )


def normalize_name(value) -> str:
    if pd.isna(value):
        return ""
    return str(value).strip()


def classify_a_type(machine_name: str) -> dict:
    name = normalize_name(
        machine_name
    )

    for rule_name, pattern in A_TYPE_EXCLUDE_RULES:
        if re.search(
            pattern,
            name,
            flags=re.IGNORECASE,
        ):
            return {
                "is_a_type": False,
                "classification_rule":
                    f"EXCLUDED:{rule_name}",
                "review_hint": "",
            }

    matched_rules = []

    for rule_name, pattern in A_TYPE_RULES:
        if re.search(
            pattern,
            name,
            flags=re.IGNORECASE,
        ):
            matched_rules.append(
                rule_name
            )

    hint_rules = []

    for rule_name, pattern in REVIEW_HINT_RULES:
        if re.search(
            pattern,
            name,
            flags=re.IGNORECASE,
        ):
            hint_rules.append(
                rule_name
            )

    return {
        "is_a_type":
            bool(
                matched_rules
            ),
        "classification_rule":
            "|".join(
                matched_rules
            ),
        "review_hint":
            "|".join(
                hint_rules
            ),
    }


def discover_all514_files() -> list[tuple[pd.Timestamp, Path]]:
    found = []

    rx = re.compile(
        r"^64_prediction_(\d{8})_all514\.csv$",
        re.IGNORECASE,
    )

    for path in SOURCE_64_DIR.glob(
        "64_prediction_????????_all514.csv"
    ):
        match = rx.match(
            path.name
        )

        if not match:
            continue

        date = pd.to_datetime(
            match.group(1),
            format="%Y%m%d",
            errors="coerce",
        )

        if pd.isna(
            date
        ):
            continue

        found.append(
            (
                pd.Timestamp(
                    date
                ),
                path,
            )
        )

    return sorted(
        found,
        key=lambda x: x[0],
    )


def resolve_source_file(
    target_date: pd.Timestamp | None,
) -> tuple[pd.Timestamp, Path]:

    files = discover_all514_files()

    if not files:
        raise RuntimeError(
            f"No 64 all514 prediction files found in:\n"
            f"{SOURCE_64_DIR}"
        )

    if target_date is None:
        return files[-1]

    target_date = pd.Timestamp(
        target_date
    ).normalize()

    for date, path in files:
        if date.normalize() == target_date:
            return (
                date,
                path,
            )

    raise FileNotFoundError(
        "No matching 64 all514 prediction found for "
        f"{target_date.date()}."
    )


def validate_source(
    df: pd.DataFrame,
    target_date: pd.Timestamp,
) -> None:

    required = [
        "machine_no",
        "machine_name",
        "score",
        "prediction_rank",
        "tier",
        "target_date",
        "latest_data_date",
    ]

    missing = [
        col
        for col in required
        if col not in df.columns
    ]

    if missing:
        raise ValueError(
            f"64 source columns missing: {missing}"
        )

    if len(df) != 514:
        raise RuntimeError(
            f"64 source has {len(df)} rows; expected 514."
        )

    machine_no = pd.to_numeric(
        df["machine_no"],
        errors="coerce",
    )

    if machine_no.nunique(
        dropna=True
    ) != 514:
        raise RuntimeError(
            "64 source does not contain 514 unique machine numbers."
        )

    if machine_no.duplicated(
        keep=False
    ).sum() != 0:
        raise RuntimeError(
            "64 source contains duplicate machine numbers."
        )

    dates = pd.to_datetime(
        df["target_date"],
        errors="coerce",
    ).dropna()

    if (
        len(dates) == 0
        or dates.nunique() != 1
        or pd.Timestamp(
            dates.iloc[0]
        ).normalize()
        != target_date.normalize()
    ):
        raise RuntimeError(
            "64 source target_date does not match filename target date."
        )


def build_a_type_tables(
    df: pd.DataFrame,
) -> tuple[
    pd.DataFrame,
    pd.DataFrame,
]:

    x = df.copy()

    classification = (
        x["machine_name"]
        .apply(
            classify_a_type
        )
        .apply(
            pd.Series
        )
    )

    x = pd.concat(
        [
            x,
            classification,
        ],
        axis=1,
    )

    review_cols = [
        "machine_no",
        "machine_name",
        "is_a_type",
        "classification_rule",
        "review_hint",
        "score",
        "prediction_rank",
        "tier",
        "target_date",
        "latest_data_date",
    ]

    review = (
        x[
            review_cols
        ]
        .sort_values(
            [
                "is_a_type",
                "machine_name",
                "machine_no",
            ],
            ascending=[
                False,
                True,
                True,
            ],
        )
        .reset_index(
            drop=True
        )
    )

    a = x[
        x["is_a_type"]
    ].copy()

    if a.empty:
        raise RuntimeError(
            "No A-type machines matched the current whitelist."
        )

    a = (
        a.sort_values(
            [
                "score",
                "prediction_rank",
                "machine_no",
            ],
            ascending=[
                False,
                True,
                True,
            ],
        )
        .reset_index(
            drop=True
        )
    )

    a[
        "a_type_rank"
    ] = (
        range(
            1,
            len(a) + 1,
        )
    )

    a[
        "a_type_tier"
    ] = "OUTSIDE_TOP10"

    a.loc[
        a["a_type_rank"] <= TOP_N,
        "a_type_tier",
    ] = "NEXT"

    a.loc[
        a["a_type_rank"] <= PRIMARY_N,
        "a_type_tier",
    ] = "PRIMARY"

    return (
        a,
        review,
    )


# ============================================================
# Main
# ============================================================

def main() -> None:
    args = parse_args()

    header(
        "74 - V4.2_C A-Type Separated Prediction"
    )

    requested_target = None

    if args.target_date:
        requested_target = pd.Timestamp(
            pd.to_datetime(
                args.target_date,
                format="%Y-%m-%d",
                errors="raise",
            )
        )

    target_date, source_path = (
        resolve_source_file(
            requested_target
        )
    )

    print(
        f"source 64 file        : {source_path}"
    )
    print(
        f"prediction target     : {target_date.date()}"
    )

    source = read_csv_flexible(
        source_path
    )

    validate_source(
        source,
        target_date,
    )

    print(
        f"source rows           : {len(source)}"
    )
    print(
        f"source unique machines: "
        f"{source['machine_no'].nunique()}"
    )

    a_type, review = (
        build_a_type_tables(
            source
        )
    )

    print(
        f"A-type machines       : {len(a_type)}"
    )

    header(
        f"{target_date.date()} A-TYPE PREDICTION TOP10"
    )

    top10 = (
        a_type.head(
            TOP_N
        ).copy()
    )

    display_cols = [
        "a_type_rank",
        "a_type_tier",
        "machine_no",
        "machine_name",
        "score",
        "prediction_rank",
        "classification_rule",
    ]

    optional_cols = [
        "avg31",
        "recent7_avg",
        "recent7_win",
        "last_diff",
        "prev_change",
        "weekday_avg",
        "type_avg",
        "plus1000_rate",
        "plus2000_rate",
        "neighbor_avg",
    ]

    display_cols += [
        c
        for c in optional_cols
        if c in top10.columns
    ]

    print(
        top10[
            display_cols
        ].to_string(
            index=False
        )
    )

    print()
    print(
        "PRIMARY = A-type ranks 1-5"
    )
    print(
        "NEXT    = A-type ranks 6-10"
    )
    print()
    print(
        "Important:"
    )
    print(
        "- Scores are reused from frozen 64 V4.2_C all514 prediction."
    )
    print(
        "- 64 normal prediction is not modified."
    )
    print(
        "- A-type classification is whitelist-based and should be reviewed."
    )
    print(
        "- This first 74 version is NOT yet an A-type-specific BB/RB model."
    )

    OUTPUT_DIR.mkdir(
        parents=True,
        exist_ok=True,
    )

    ymd = target_date.strftime(
        "%Y%m%d"
    )

    all_a_path = (
        OUTPUT_DIR
        / f"74_A_type_prediction_{ymd}_all.csv"
    )

    top10_path = (
        OUTPUT_DIR
        / f"74_A_type_prediction_{ymd}_top10.csv"
    )

    review_path = (
        OUTPUT_DIR
        / f"74_A_type_candidate_review_{ymd}.csv"
    )

    metadata_path = (
        OUTPUT_DIR
        / f"74_A_type_prediction_{ymd}_metadata.csv"
    )

    a_type.to_csv(
        all_a_path,
        index=False,
        encoding="utf-8-sig",
    )

    top10.to_csv(
        top10_path,
        index=False,
        encoding="utf-8-sig",
    )

    review.to_csv(
        review_path,
        index=False,
        encoding="utf-8-sig",
    )

    metadata = pd.DataFrame(
        [
            {
                "target_date":
                    target_date.date(),
                "source_64_file":
                    source_path.name,
                "source_model":
                    (
                        source["tier"]
                        .notna()
                        .any()
                    ),
                "source_rows":
                    int(
                        len(source)
                    ),
                "a_type_machines":
                    int(
                        len(a_type)
                    ),
                "top_n":
                    TOP_N,
                "primary_n":
                    PRIMARY_N,
                "score_recalculated":
                    False,
                "normal_prediction_modified":
                    False,
                "classification_policy":
                    "conservative_name_whitelist",
                "a_type_specific_bb_rb_model":
                    False,
            }
        ]
    )

    metadata.to_csv(
        metadata_path,
        index=False,
        encoding="utf-8-sig",
    )

    header(
        "FILES SAVED"
    )

    for path in (
        all_a_path,
        top10_path,
        review_path,
        metadata_path,
    ):
        print(path)

    print()
    print(
        "74 A-type separated prediction complete."
    )


if __name__ == "__main__":
    main()
